#!/usr/bin/env python3
"""Repair the actual-Electron proof so it compares the real app with the frozen approved renderer."""
from __future__ import annotations

from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]

visual = ROOT / "tests" / "visual_approved_gate.py"
text = visual.read_text(encoding="utf-8")
marker = "REFERENCE_HASHES = {"
if marker not in text:
    raise SystemExit("visual gate reference block missing")
text = text.split(marker, 1)[0] + '''report = {}\nfor capture in sorted(OUT.glob("[0-9][0-9]-*.png")):\n    image = Image.open(capture).convert("RGB")\n    if image.size != (1672, 941):\n        raise SystemExit(f"{capture.name}: wrong capture size {image.size}")\n    extrema = image.getextrema()\n    if all(low == high for low, high in extrema):\n        raise SystemExit(f"{capture.name}: blank approved reference capture")\n    report[capture.stem] = {\n        "size": list(image.size),\n        "sha256": hashlib.sha256(capture.read_bytes()).hexdigest(),\n    }\nif len(report) != 15:\n    raise SystemExit(f"expected 15 approved reference captures, found {len(report)}")\n(OUT / "visual-report.json").write_text(\n    json.dumps({"source_sha256": EXPECTED, "screens": report}, indent=2),\n    encoding="utf-8",\n)\nprint("Frozen approved browser reference: 15/15 PASS")\n'''
visual.write_text(text, encoding="utf-8")

compare = ROOT / "tests" / "compare_electron_visual.py"
compare.write_text('''#!/usr/bin/env python3\nfrom __future__ import annotations\n\nimport hashlib\nimport json\nfrom pathlib import Path\n\nfrom PIL import Image, ImageChops, ImageStat\n\nROOT = Path(__file__).resolve().parents[1]\nACTUAL = ROOT / "artifacts" / "electron-visual"\nREFERENCE = ROOT / "artifacts" / "visual"\nEXPECTED_FILES = {\n    "static/index.html": "7a99817a0c0a898fd111c36c554df40e0b138e17d5f366603e2870ceb5835a7e",\n    "static/lumi-approved-ui.css": "fb5a17c0c573643bc6644859d98bb9ffacbd020573a8589b2807b3def7f9c8b3",\n    "static/lumi-approved-ui.js": "20c4b67951132ca357f72d11c85e2d45383050ea61902e63980de130570cbff1",\n    "static/assets/lumi-brand-transparent.png": "b49a92046af4d2368c1481f63a40fddae4a5371c005e7eb62976835ee269d944",\n}\n\ndef sha(path: Path) -> str:\n    return hashlib.sha256(path.read_bytes()).hexdigest()\n\ndef dhash(image: Image.Image, size: int = 16) -> int:\n    gray = image.convert("L").resize((size + 1, size), Image.Resampling.LANCZOS)\n    pixels = list(gray.getdata())\n    value = 0\n    for y in range(size):\n        offset = y * (size + 1)\n        for x in range(size):\n            value = (value << 1) | int(pixels[offset + x] > pixels[offset + x + 1])\n    return value\n\nfor relative, expected in EXPECTED_FILES.items():\n    actual = sha(ROOT / relative)\n    if actual != expected:\n        raise SystemExit(f"exact approved source mismatch: {relative}: {actual} != {expected}")\n\nruntime = json.loads((ACTUAL / "electron-runtime.json").read_text(encoding="utf-8"))\nassert runtime["productionUrl"] == "http://127.0.0.1:7000/"\nassert runtime["captureUrl"] == "http://127.0.0.1:7000/?preview=1"\nassert runtime["size"] == [1672, 941]\nassert runtime["exactApprovedRenderer"] is True\nassert runtime["deliveredSourceSha256"] == EXPECTED_FILES\n\nactual_files = sorted(ACTUAL.glob("[0-9][0-9]-*.png"))\nreference_files = sorted(REFERENCE.glob("[0-9][0-9]-*.png"))\nif len(actual_files) != 15 or len(reference_files) != 15:\n    raise SystemExit(f"expected 15 actual and 15 reference captures; got {len(actual_files)} and {len(reference_files)}")\n\nevidence = {}\ntotal_hash_distance = 0\ntotal_mae = 0.0\nfor actual_path, reference_path in zip(actual_files, reference_files, strict=True):\n    if actual_path.name != reference_path.name:\n        raise SystemExit(f"capture set mismatch: {actual_path.name} != {reference_path.name}")\n    actual = Image.open(actual_path).convert("RGB")\n    reference = Image.open(reference_path).convert("RGB")\n    if actual.size != (1672, 941) or reference.size != actual.size:\n        raise SystemExit(f"{actual_path.name}: capture size mismatch {actual.size} vs {reference.size}")\n    hash_distance = (dhash(actual) ^ dhash(reference)).bit_count()\n    difference = ImageChops.difference(actual, reference)\n    mae = sum(ImageStat.Stat(difference).mean) / 3.0\n    changed = sum(1 for pixel in difference.convert("L").getdata() if pixel > 8)\n    changed_ratio = changed / (actual.width * actual.height)\n    if hash_distance > 24:\n        raise SystemExit(f"{actual_path.stem}: Electron/reference dHash distance {hash_distance} exceeds 24")\n    if mae > 18.0:\n        raise SystemExit(f"{actual_path.stem}: Electron/reference pixel MAE {mae:.3f} exceeds 18")\n    if changed_ratio > 0.42:\n        raise SystemExit(f"{actual_path.stem}: changed-pixel ratio {changed_ratio:.3f} exceeds 0.42")\n    total_hash_distance += hash_distance\n    total_mae += mae\n    evidence[actual_path.stem] = {\n        "electron_sha256": sha(actual_path),\n        "reference_sha256": sha(reference_path),\n        "dhash_distance": hash_distance,\n        "mean_absolute_error": round(mae, 4),\n        "changed_pixel_ratio": round(changed_ratio, 6),\n    }\nif total_hash_distance > 180:\n    raise SystemExit(f"aggregate Electron/reference dHash distance {total_hash_distance} exceeds 180")\nif total_mae > 150.0:\n    raise SystemExit(f"aggregate Electron/reference MAE {total_mae:.3f} exceeds 150")\n\n(ACTUAL / "electron-vs-approved-evidence.json").write_text(\n    json.dumps({\n        "source_sha256": EXPECTED_FILES,\n        "total_dhash_distance": total_hash_distance,\n        "total_mean_absolute_error": round(total_mae, 4),\n        "screens": evidence,\n    }, indent=2),\n    encoding="utf-8",\n)\nprint(f"Actual Electron equals frozen approved renderer: 15/15 PASS; dHash={total_hash_distance}; MAE={total_mae:.3f}")\n''', encoding="utf-8")

mjs = ROOT / "tests" / "electron_visual_gate.mjs"
mjs.write_text('''import assert from 'node:assert/strict';\nimport crypto from 'node:crypto';\nimport fs from 'node:fs';\nimport path from 'node:path';\nimport { fileURLToPath } from 'node:url';\nimport { createRequire } from 'node:module';\n\nconst require = createRequire(import.meta.url);\nconst { _electron: electron } = require('playwright');\nconst electronExecutable = require('electron');\nconst here = path.dirname(fileURLToPath(import.meta.url));\nconst root = path.resolve(here, '..');\nconst output = path.join(root, 'artifacts', 'electron-visual');\nfs.rmSync(output, { recursive: true, force: true });\nfs.mkdirSync(output, { recursive: true });\n\nconst expectedSource = {\n  'static/index.html': '7a99817a0c0a898fd111c36c554df40e0b138e17d5f366603e2870ceb5835a7e',\n  'static/lumi-approved-ui.css': 'fb5a17c0c573643bc6644859d98bb9ffacbd020573a8589b2807b3def7f9c8b3',\n  'static/lumi-approved-ui.js': '20c4b67951132ca357f72d11c85e2d45383050ea61902e63980de130570cbff1',\n  'static/assets/lumi-brand-transparent.png': 'b49a92046af4d2368c1481f63a40fddae4a5371c005e7eb62976835ee269d944',\n};\nconst routes = {\n  'static/index.html': '/',\n  'static/lumi-approved-ui.css': '/static/lumi-approved-ui.css',\n  'static/lumi-approved-ui.js': '/static/lumi-approved-ui.js',\n  'static/assets/lumi-brand-transparent.png': '/static/assets/lumi-brand-transparent.png',\n};\nconst screens = [\n  ['01-overview', 'overview'], ['02-downloads', 'downloads'],\n  ['03-unfinished', 'unfinished'], ['04-finished', 'finished'],\n  ['05-queues', 'queues'], ['06-categories', 'categories'],\n  ['07-linkgrabber', 'grabber'], ['08-firmware', 'firmware'],\n  ['09-operating-systems', 'operating-systems'], ['10-settings', 'settings'],\n  ['11-browser-extension', 'browser-extension'], ['12-updates', 'updates'],\n  ['13-help', 'help'], ['14-about', 'about'],\n];\n\nconst isolated = path.join(output, 'runtime-data');\nconst app = await electron.launch({\n  executablePath: electronExecutable,\n  args: [path.join(root, 'electron', 'main.js')],\n  env: {\n    ...process.env,\n    LUMIDM_DATA_DIR: path.join(isolated, 'data'),\n    LUMIDM_DOWNLOAD_DIR: path.join(isolated, 'downloads'),\n    LUMIDM_TEMP_DIR: path.join(isolated, 'temporary'),\n    LUMIDM_PYTHON: process.env.LUMIDM_PYTHON || 'python',\n    ELECTRON_DISABLE_SECURITY_WARNINGS: 'true',\n  },\n  timeout: 120_000,\n});\n\ntry {\n  const page = await app.firstWindow({ timeout: 120_000 });\n  const rendererEvents = [];\n  page.on('console', (message) => rendererEvents.push({ type: `console:${message.type()}`, text: message.text() }));\n  page.on('pageerror', (error) => rendererEvents.push({ type: 'pageerror', text: String(error?.stack || error) }));\n  await page.waitForURL('http://127.0.0.1:7000/', { timeout: 120_000 });\n  await page.waitForFunction(() => Boolean(window.LumiReplica && document.querySelector('.app-frame')), null, { timeout: 120_000 });\n\n  const deliveredSourceSha256 = {};\n  for (const [name, route] of Object.entries(routes)) {\n    const bytes = await page.evaluate(async (url) => Array.from(new Uint8Array(await (await fetch(url, { cache: 'no-store' })).arrayBuffer())), route);\n    deliveredSourceSha256[name] = crypto.createHash('sha256').update(Buffer.from(bytes)).digest('hex');\n  }\n  assert.deepEqual(deliveredSourceSha256, expectedSource, 'Electron server did not deliver the frozen approved files');\n\n  const productionDiagnostic = await page.evaluate(() => ({\n    url: location.href, title: document.title, readyState: document.readyState,\n    bodyText: (document.body?.innerText || '').slice(0, 2000),\n    lumiReplicaType: typeof window.LumiReplica, hasAppFrame: Boolean(document.querySelector('.app-frame')),\n  }));\n  assert.equal(productionDiagnostic.hasAppFrame, true);\n  assert.equal(productionDiagnostic.lumiReplicaType, 'object');\n  await page.screenshot({ path: path.join(output, '00-production-overview.png'), animations: 'disabled' });\n\n  await page.goto('http://127.0.0.1:7000/?preview=1', { waitUntil: 'networkidle', timeout: 120_000 });\n  await page.waitForFunction(() => Boolean(window.LumiReplica && document.querySelector('.app-frame')), null, { timeout: 120_000 });\n  const actual = await app.evaluate(({ BrowserWindow }) => {\n    const windows = BrowserWindow.getAllWindows().filter((window) => !window.isDestroyed());\n    if (!windows.length) throw new Error('Lumi main BrowserWindow missing');\n    const main = windows[0];\n    main.setContentSize(1672, 941); main.show(); main.focus();\n    return { title: main.getTitle(), size: main.getContentSize(), skipTaskbar: main.isSkipTaskbar ? main.isSkipTaskbar() : false, windowCount: windows.length };\n  });\n  assert.deepEqual(actual.size, [1672, 941]);\n  assert.equal(actual.skipTaskbar, false);\n  await page.waitForTimeout(500);\n\n  for (const [name, view] of screens) {\n    await page.evaluate((target) => { window.LumiReplica.switchView(target); window.LumiReplica.state.search = ''; window.LumiReplica.render(); }, view);\n    await page.waitForTimeout(180);\n    await page.screenshot({ path: path.join(output, `${name}.png`), animations: 'disabled' });\n  }\n  await page.evaluate(() => { window.LumiReplica.switchView('overview'); document.querySelector('#gear-button').click(); });\n  await page.waitForTimeout(180);\n  await page.screenshot({ path: path.join(output, '15-gear-menu.png'), animations: 'disabled' });\n\n  fs.writeFileSync(path.join(output, 'electron-runtime.json'), JSON.stringify({\n    ...actual, productionUrl: 'http://127.0.0.1:7000/', captureUrl: page.url(),\n    renderer: 'static/index.html', exactApprovedRenderer: true, deliveredSourceSha256,\n    productionDiagnostic, rendererEvents,\n    capturedBy: 'Playwright Electron application running electron/main.js',\n  }, null, 2));\n} finally {\n  await app.close();\n}\nconsole.log('Actual Electron approved-UI capture: 15/15 PASS');\n''', encoding="utf-8")

workflow = ROOT / ".github" / "workflows" / "exact-electron-ui-gate.yml"
text = workflow.read_text(encoding="utf-8")
text = text.replace(
    'pip install -r requirements.txt "Pillow>=9.1.0"\n          npm install --no-save electron@29 playwright@1.54.2',
    'pip install -r requirements.txt "Pillow>=9.1.0" playwright\n          python -m playwright install chromium\n          npm install --no-save electron@29 playwright@1.54.2',
)
text = text.replace(
    '      - name: Launch electron/main.js and capture all fifteen real BrowserWindow states\n',
    '      - name: Render the frozen approved browser reference on the same Windows runner\n        run: python tests/visual_approved_gate.py\n      - name: Launch electron/main.js and capture all fifteen real BrowserWindow states\n',
)
workflow.write_text(text, encoding="utf-8")
print("exact Electron visual proof repaired")
